nextflow_process {

    name "Test Process RPBP_PREPAREGENOME"
    script "../main.nf"
    process "RPBP_PREPAREGENOME"

    tag "modules"
    tag "modules_nfcore"
    tag "rpbp"
    tag "rpbp/preparegenome"
    tag "gunzip"

    setup {
        run("GUNZIP") {
            script "modules/nf-core/gunzip/main.nf"
            process {
            """
            input[0] = [
                [ id:'reference' ],
                file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.dna.chromosome.20.fa.gz", checkIfExists: true)
            ]
            """
            }
        }
    }

    test("homo_sapiens chr20 - prepare genome") {

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip
                    .map { meta, fa -> [
                        meta,
                        fa,
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.111_chr20.gtf", checkIfExists: true)
                    ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("homo_sapiens chr20 - prepare genome - extended start codons") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip
                    .map { meta, fa -> [
                        meta,
                        fa,
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.111_chr20.gtf", checkIfExists: true)
                    ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("homo_sapiens chr20 - prepare genome - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip
                    .map { meta, fa -> [
                        meta,
                        fa,
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.111_chr20.gtf", checkIfExists: true)
                    ] }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

